insert into tracks(slug,badge,tone,side,title,description,bullets,foot_label,cta_label,sort) values('admissions','CAPS & CUTOFFS','neutral','Strategic Advisory','University Admissions Advisory','Prevent the heartbreaking error of selecting unaccredited combinations or missing catchment quotas. We manage your JAMB CAPS until green matriculation.',ARRAY['Federal & State Catchment calibration','Change of institution & course vetting','Direct clearance troubleshooting'],'Personal 1-on-1 Guidance','Consult',4) on conflict(slug) do update set badge=excluded.badge,tone=excluded.tone,side=excluded.side,title=excluded.title,description=excluded.description,bullets=excluded.bullets,foot_label=excluded.foot_label,cta_label=excluded.cta_label,sort=excluded.sort;
insert into tracks(slug,badge,tone,side,title,description,bullets,foot_label,cta_label,sort) values('cbt','SIMULATION LAB','emerald','Physical In-Center','Timed CBT Practice Lab','Overcome computer anxiety and pacing problems. Practice inside our dedicated desktop terminal suite calibrated exactly to official testing interfaces.',ARRAY['Exact 8-key keyboard navigation practice','Immediate score breakdown & review','Weak-subject question clustering'],'Weekly Mock Access','Book Slot',5) on conflict(slug) do update set badge=excluded.badge,tone=excluded.tone,side=excluded.side,title=excluded.title,description=excluded.description,bullets=excluded.bullets,foot_label=excluded.foot_label,cta_label=excluded.cta_label,sort=excluded.sort;
