insert into pillars(icon,title,copy,tag,tag_icon,tone,sort) values('assignment_turned_in','Follow-Through Past Results Day','High scores mean nothing if you are not admitted. We advise on Post-UTME cutoff patterns, O-Level combination blending, and CAPS approval until matriculation.','Coaching Until Matriculation','verified_user','secondary',1);
insert into pillars(icon,title,copy,tag,tag_icon,tone,sort) values('shield','Honest Scope & Zero Gimmicks','No fake scholarship guarantees, no counterfeit “special centers”, and no unvetted promises. We believe in transparent, merit-driven Nigerian and overseas preparation.','Ethical Integrity','check_circle','primary',2);
insert into pillars(icon,title,copy,tag,tag_icon,tone,sort) values('contact_support','Free First Diagnostic Consultation','Walk into our Banana Estate / Laara center or join our online diagnostic assessment session. We review your past attempts and formulate a customized syllabus roadmap for free.','100% Free Consultation','arrow_forward','secondary',3);
