insert into testimonials(scope,quote,initials,name,detail,area,sort) values('parents','What distinguishes ADJ from tutorial centers in Ikorodu is the absolute discipline. If my son was five minutes late, I received an SMS. Their weekly diagnostic mock exams left no room for complacency. When his UTME result came out at 342, we knew every naira spent at the Laara center was an investment that delivered.','FA','Mrs. F. Adeleke','Parent of Babatunde Adeleke (Mechanical Engineering, UNILAG)','Resident, Banana Estate, Off Igbe Road',0);
insert into testimonials(scope,quote,initials,name,detail,area,sort) values('parents','We had spent two consecutive years falling victim to fake admission promises from agents. ADJ took over our daughter''s case, sat us down, and explained the exact cutoff quota system for LASU Law. Through their JUPEB program, she scored 15 points and entered 200 Level directly without stress.','GO','Mr. G. Ogunsanya','Parent of Tunde Oladipupo (200L Law, LASU)','Agunfoye-Igbogbo Axis, Ikorodu',1);
insert into testimonials(scope,quote,initials,name,detail,area,sort) values('home','“Before ADJ, I spent two years stuck at 210 with self-study. Their CBT lab drills eliminated my timing anxiety, and Mr. Daniel personally guided my change of course to Medicine at UNILAG. I am now in my second year.”','FB','Favour Balogun','Medicine & Surgery, UNILAG (Igbogbo Alum)','',0);
insert into testimonials(scope,quote,initials,name,detail,area,sort) values('home','“The group-only lectures kept all of us awake. No student was left behind during tough Organic Chemistry derivations. Gaining 200 Level Direct Entry to LASU Law without retaking JAMB was the best decision my parents made.”','TO','Tunde Oladipupo','Faculty of Law, LASU (Igbe-Laara)','',1);
insert into testimonials(scope,quote,initials,name,detail,area,sort) values('home','“What sets ADJ apart from every other tutorial in Ikorodu is honesty. When other centers were demanding exorbitant sums for “assurance”, ADJ clearly mapped out my daughter’s OAU catchment standing and she got in on pure merit.”','EA','Mrs. E. Adeleke','Mother of Mechanical Eng. Scholar, OAU','',2);
insert into program_pages(slug,h1,lead,stats,sections) values('jamb','JAMB / UTME Exam Clinic & High-Score Mastery','Targeted academic preparation precision-engineered to secure 280+ scores for hyper-competitive admissions into UNILAG, LASU, UI, OAU, FUTA, and premier federal institutions. Structured coaching until your name appears on the matriculation register.','{"numbers": ["342 / 400", "Made Median", "87%"], "labels": ["2024 Top Score", "Average Improvement", "Pass Rate Benchmarking"]}',ARRAY['{"title": "Curriculum Architecture & Phase Breakdown", "blocks": [{"t": "p", "v": "We don''t rely on passive cramming. Our structured 4-phase trajectory guides secondary leavers through systematic syllabus elimination to high-speed timed mastery."}, {"t": "h3", "v": "Deep Syllabus Coverage & Core Topic Mastery"}, {"t": "p", "v": "Granular topic deconstruction based on the official JAMB Unified Syllabus. Students are divided into disciplined focus departments:"}, {"t": "list", "v": ["Mandatory General: Use of English (Grammar, Lexis, Stress Patterns & Antonyms)."]}, {"t": "list", "v": ["Sciences & Engineering: Advanced Physics, General Chemistry, Biology & Mathematics."]}, {"t": "list", "v": ["Management & Arts: Government, Literature, Economics, CRK/IRS, and Accounting."]}, {"t": "h3", "v": "Compulsory Novel Analysis & Literary Breakdown"}, {"t": "p", "v": "Every point in the general English section counts. We dissect the prescribed JAMB reading text line by line to guarantee full marks in literature questions:"}, {"t": "list", "v": ["Scene-by-scene character motivations, contextual themes, and thematic ironies."]}, {"t": "list", "v": ["Over 500 custom-generated contextual extract questions unique to ADJ Consultants."]}, {"t": "list", "v": ["Rapid character-relationship charts and vocabulary memorization primers."]}, {"t": "h3", "v": "Speed & Accuracy CBT Drills in Laara Computer Lab"}, {"t": "p", "v": "Transition from manual pen-and-paper mastery to computerized operational agility inside our dedicated Greater Heights partner lab:"}, {"t": "list", "v": ["Elimination of mouse reliance: drill keyboard shortcuts (A, B, C, D, N, P, S)."]}, {"t": "list", "v": ["Sub-40-second problem-solving metrics for calculation-heavy disciplines."]}, {"t": "list", "v": ["Real-time heatmaps identifying syllabus weak points on student dashboard."]}, {"t": "h3", "v": "Full-Scale Timed Mock Marathons (Negative Conditioning)"}, {"t": "p", "v": "Total cognitive conditioning under stressful simulated testing conditions identical to the official JAMB testing protocol:"}, {"t": "list", "v": ["Bi-weekly Saturday mock marathons running 180 questions in exactly 120 minutes."]}, {"t": "list", "v": ["Pressure-test psychological conditioning to eradicate test anxiety and panic stalls."]}, {"t": "list", "v": ["Post-mock one-on-one strategy review with seasoned ADJ Lead Examiners."]}]}','{"title": "Wrong Subject Combination Disqualifies More Students Than Low Scores.", "blocks": [{"t": "p", "v": "Every year, hundreds of brilliant students score 270+ but are denied admission simply because their chosen subjects conflict with university faculty brochures. At ADJ, our consultants verify and cross-reference your four subjects before you complete your JAMB profile code registration."}, {"t": "h4", "v": "Medicine & Surgery / Nursing"}, {"t": "p", "v": "Strict Mandate: Mathematics is mandatory for O''Level, plus Biology, Chemistry & Physics in UTME."}, {"t": "h4", "v": "Accounting / Finance / Banking"}, {"t": "p", "v": "LASU requires Mathematics, Economics plus any Social Science or Commercial subject."}, {"t": "h4", "v": "Law / Jurisprudence"}, {"t": "p", "v": "Literature-in-English is strictly non-negotiable alongside Arts or Social Science electives."}, {"t": "h4", "v": "Computer Science & Engineering"}, {"t": "p", "v": "Both institutions reject Biology for Engineering admissions. Technical subjects must align."}]}','{"title": "Physical & Virtual Class Cohorts", "blocks": [{"t": "p", "v": "Tailored schedules serving full-time secondary school leavers, WAEC retakers, and working candidates residing across the Ikorodu division."}, {"t": "h3", "v": "Morning Immersion Batch"}, {"t": "p", "v": "Designed for high-intensity secondary school leavers dedicating full daylight hours to exam mastery and daily laboratory drills."}, {"t": "h3", "v": "Afternoon Accelerated Batch"}, {"t": "p", "v": "Engineered for SS3 students finishing school hours or candidates requiring accelerated syllabus recaps and CBT familiarization."}, {"t": "h3", "v": "Evening & Weekend Virtual"}, {"t": "p", "v": "Interactive live streamed masterclasses with real-time screen sharing, cloud quiz portals, and Sunday replay access."}, {"t": "h3", "v": "Facility Partner: Greater Heights Tutorial Center"}, {"t": "p", "v": "ADJ Educational Consultants conducts its rigorous CBT simulation tracks and physical cohorts in strategic collaboration with Greater Heights Tutorial Center at Banana Estate / Laara, Ikorodu."}]}','{"title": "Claim Your Free Baseline CBT Diagnostic & Admission Audit", "blocks": [{"t": "p", "v": "Take a complimentary 90-minute timed mock in our Laara CBT lab. Receive an immediate breakdown of your speed per subject, syllabus deficiency gaps, and a confirmed assessment of your course eligibility."}, {"t": "h3", "v": "Schedule Your Session"}, {"t": "p", "v": "No consultation fee required. Physical and online slots available."}]}']) on conflict(slug) do update set h1=excluded.h1,lead=excluded.lead,stats=excluded.stats,sections=excluded.sections;
insert into program_pages(slug,h1,lead,stats,sections) values('waec','WAEC & NECO Intensive: High-Distinction Syllabus Mastery & Practical Lab Prep','Rigorous curriculum deconstruction targeting 7-9 A1/B2/B3 credits for SS3 candidates and GCE private scholars across Ikorodu division. Complete with physical practical wet-labs and WAEC Chief Examiner rubric coaching.','{"numbers": ["9 A1s", "Made Median", "4.2 hrs"], "labels": ["Made Median", "Average Improvement", "Weekly Lab Hours"]}',ARRAY['{"title": "Core Departmental Syllabi Tracks", "blocks": [{"t": "p", "v": "Deconstructed line-by-line according to the latest WAEC/NECO harmonized curriculum with heavy emphasis on scoring criteria."}, {"t": "h3", "v": "Science Department"}, {"t": "p", "v": "Built for aspiring engineers, medical practitioners, and computer scientists requiring pure distinctions."}, {"t": "list", "v": ["Further Mathematics: Matrices, Calculus, Vectors & Mechanics speed-drills."]}, {"t": "list", "v": ["Physics: Alternative to Practical & hands-on Wet Lab drills for optics and mechanics."]}, {"t": "list", "v": ["Chemistry: Volumetric (Acid-Base) & Qualitative inorganic salt analysis."]}, {"t": "list", "v": ["Biology: Specimen identification, magnification rules, and diagrammatic scoring."]}, {"t": "h3", "v": "Commercial Department"}, {"t": "p", "v": "Designed for future accountants, bankers, and economists demanding absolute calculation balance."}, {"t": "list", "v": ["Financial Accounting: Ledger balances, double entry protocols, and Final Account balance sheet precision."]}, {"t": "list", "v": ["Commerce: Trade documentation, banking instruments, and stock exchange mechanisms."]}, {"t": "list", "v": ["Economics: Micro/Macro graph interpretations, elasticity calculation speed, and national income data."]}, {"t": "list", "v": ["Marketing: Consumer behavior analysis, distribution channels, and promotional strategy rubric answers."]}, {"t": "h3", "v": "Arts & Humanities"}, {"t": "p", "v": "Targeted for future legal advocates, diplomats, literary scholars, and mass media professionals."}, {"t": "list", "v": ["Literature-in-English: Comprehensive character deconstruction of prescribed African & Non-African Prose, Drama, and Poetry."]}, {"t": "list", "v": ["Government: Constitutional developments in Nigeria, public administration, and political theory models."]}, {"t": "list", "v": ["CRK / IRS: Scriptural texts, religious doctrines, moral implications, and topical exam question rubrics."]}, {"t": "list", "v": ["Civic Education: Human rights tenets, national values, responsible citizenship, and community laws."]}]}','{"title": "WAEC & NECO Chief Examiner Rubric Coaching", "blocks": [{"t": "p", "v": "Most students lose marks not from lack of knowledge, but due to technical violations of the WAEC Marking Scheme. Our scholars are coached directly on Chief Examiner grading templates to retain every fractional point."}, {"t": "h4", "v": "2005 - 2024 Past Question Marathon"}, {"t": "p", "v": "Full 20-year archival access with step-by-step model solutions formulated specifically by vetted certified WAEC & NECO markers."}, {"t": "h4", "v": "Step-Marking Breakdown"}, {"t": "p", "v": "WAEC awards M (Method), A (Accuracy), and B (Independent) marks. Omitting the standard algebraic sequence yields immediate 0 even if the final numerical answer is correct."}, {"t": "h4", "v": "Unit Omission Docks"}, {"t": "p", "v": "Failure to append correct S.I. units (e.g., $N/m^2$, $ms^{-1}$) at the final step docks 1 full mark per question, resulting in cumulative grade degradation across Section B."}, {"t": "h4", "v": "Essay Structural Strictness"}, {"t": "p", "v": "Rigid adherence to Content, Organization, Expression, and Mechanical Accuracy (COEM). Formal letters with punctuation flaws in recipient addresses are immediately penalized."}, {"t": "h4", "v": "Diagram Magnification"}, {"t": "p", "v": "Diagrams must use clean un-feathered lines, clear label guidelines without arrowheads, explicit magnification titles ($\\times 1.5$ to $\\times 2.0$), and proportional accuracy."}]}','{"title": "Hands-On Physical Wet-Labs & Apparatus Drills", "blocks": [{"t": "p", "v": "Most students struggle with Alternative to Practical or wet-lab examinations due to lack of exposure. At ADJ, candidates handle physical scientific apparatus weekly, mastering exact reading measurements before exam day."}]}','{"title": "Cohort Schedules & Batch Timing", "blocks": [{"t": "p", "v": "Carefully structured shifts designed to accommodate full-time private candidates as well as enrolled secondary school scholars in surrounding Ikorodu schools."}, {"t": "h3", "v": "SS3 School Leavers & Morning Immersion"}, {"t": "p", "v": "Full daytime immersion tailored for GCE private scholars and high school graduates sitting upcoming exam diets."}, {"t": "h3", "v": "SS3 After-School Booster"}, {"t": "p", "v": "Supplemental syllabus coverage for current students attending high schools across Igbogbo, Elepe, and Ikorodu Central."}, {"t": "h3", "v": "Saturday Practical & Mock Drill"}, {"t": "p", "v": "Intensive wet-lab runs, speed-timing tests, and full-length exam simulations mirroring WAEC/NECO conditions."}]}','{"title": "Schedule Free O-Level Diagnostic Test", "blocks": [{"t": "p", "v": "Evaluate current subject strengths and weak areas before registration. Includes our comprehensive syllabus diagnostic and a 1-on-1 performance review with an ADJ academic advisor."}, {"t": "h3", "v": "Book Diagnostic Session"}, {"t": "p", "v": "Fill in details for candidate or guardian to reserve a diagnostic desk."}]}']) on conflict(slug) do update set h1=excluded.h1,lead=excluded.lead,stats=excluded.stats,sections=excluded.sections;
insert into program_pages(slug,h1,lead,stats,sections) values('jupeb','JUPEB Direct Entry: Skip 100-Level Straight into Year Two','','{"numbers": ["14 Pts", "Made Median", "78%"], "labels": ["Made Median", "Average Improvement", "Pass Rate Benchmarking"]}',ARRAY['{"title": "Understanding JUPEB Direct Entry: The Proven 200L Pathway", "blocks": [{"t": "p", "v": "Why spend another stressful cycle waiting for UTME re-takes when you can complete your entire Year 1 curriculum within a focused, supervised academic institution in Ikorodu?"}, {"t": "h3", "v": "What is JUPEB?"}, {"t": "p", "v": "The Joint Universities Preliminary Examinations Board (JUPEB) is an apex national academic examination board established by a consortium of leading Federal Universities and led by the University of Lagos."}, {"t": "h3", "v": "Why JUPEB Over JAMB?"}, {"t": "list", "v": ["Zero Lost Year: You matriculate directly into 200-Level, catching up with secondary school peers already in university."]}, {"t": "list", "v": ["UTME Bottleneck Immunity: Protect yourself against annual mass score deductions and arbitrary center technical glitches."]}, {"t": "list", "v": ["Focus on 3 Subjects: Master only the 3 academic disciplines directly relevant to your target faculty."]}, {"t": "h3", "v": "Grading & Assessment Model"}, {"t": "p", "v": "Unlike the one-shot 2-hour UTME computer test, JUPEB mirrors university semester evaluation standards, rewarding consistent study and discipline throughout the year:"}]}','{"title": "3-Subject Combinations & Cut-Off Targets", "blocks": [{"t": "p", "v": "Candidates are evaluated on a 16-point scale (5 points per subject + 1 bonus point for no grade ''F''). Match your dream university faculty with our disciplined syllabus tracks:"}, {"t": "h3", "v": "Medicine & Life Sciences"}, {"t": "p", "v": "Includes mandatory Saturday wet-lab practicals at our partner science center in Ikorodu."}, {"t": "h3", "v": "Engineering & Technology"}, {"t": "p", "v": "Intensive calculus drills, mechanics masterclasses, and applied physics problem-solving."}, {"t": "h3", "v": "Law & Humanities"}, {"t": "p", "v": "Rigorous essay synthesis, constitutional critique tutorials, and textual analysis seminars."}, {"t": "h3", "v": "Management & Social Sciences"}, {"t": "p", "v": "Focus on corporate ledger management, microeconomic models, and data analytics logic."}]}','{"title": "Academic Structure & Rigor at Banana Estate / Laara Center", "blocks": [{"t": "p", "v": "We do not run JUPEB like a casual afternoon tutorial class. Our facility in Banana Estate operates with collegiate seriousness designed to transition senior secondary school leavers into confident second-year university scholars."}, {"t": "h4", "v": "A-Level Standard Syllabi"}, {"t": "p", "v": "Directly equivalent to 100-Level university coursework, taught by university adjunct lecturers and experienced board examiners."}, {"t": "h4", "v": "Bi-Weekly University-Graded Tests"}, {"t": "p", "v": "Continuous assessment with transparent score notifications shared directly with parents via SMS & WhatsApp reports."}, {"t": "h4", "v": "Strict 20-Scholar Cohort Limit"}, {"t": "p", "v": "No crowded auditoriums. High accountability, mandatory study hours, and hostel partner accommodations within Igbe-Laara for distant students."}, {"t": "h3", "v": "Standard Scholar Weekly Rhythm"}, {"t": "p", "v": "Structured 5-day lecture model with supervised Saturday mock diagnostics"}, {"t": "h4", "v": "Theory Lectures"}, {"t": "p", "v": "Comprehensive syllabus coverage, theoretical proofs, and textbook deconstruction."}, {"t": "h4", "v": "Past Question Clinics"}, {"t": "p", "v": "10-year JUPEB external board past question drills, error pattern elimination."}, {"t": "h4", "v": "Lab Practicals & Mocks"}, {"t": "p", "v": "Titrations, optics, biological taxonomy specimens, and timed essay evaluations."}]}','{"title": "Transparent Investment & Admissions Processing Guarantee", "blocks": [{"t": "p", "v": "No hidden levies. No sudden syllabus surcharges. We provide complete advisory on overall board registration fees, laboratory levies, and flexible installment arrangements."}, {"t": "h3", "v": "Transparent Fee Schedule"}, {"t": "p", "v": "JUPEB tuition is an investment into skipping an entire year of university hostel and tuition fees. During your free syllabus diagnostic consultation, our senior educational coordinator will outline:"}, {"t": "h3", "v": "\"Coaching Until Matriculation\""}, {"t": "p", "v": "Our responsibility does not conclude when you write the final JUPEB exam. We handle the crucial second-half transition:"}, {"t": "list", "v": ["JAMB Direct Entry Form Portal: Guided subject combination cross-checking and bio-data submission."]}, {"t": "list", "v": ["Transcript Dispatch to Universities: Direct institutional forwarding of verified JUPEB result transcripts to UNILAG, LASU, UI, OAU, FUTA."]}, {"t": "list", "v": ["Faculty Screening Support: Document verification guidance until the physical matriculation oath is administered."]}]}','{"title": "Check Your University Eligibility & Subject Combination", "blocks": [{"t": "p", "v": "Submit your desired university course and O-Level standing. Our academic team in Banana Estate / Laara will assess your 200L qualification route within 24 hours."}]}']) on conflict(slug) do update set h1=excluded.h1,lead=excluded.lead,stats=excluded.stats,sections=excluded.sections;
insert into program_pages(slug,h1,lead,stats,sections) values('international','International Examinations: High-Band IELTS & Digital SAT Mastery in Ikorodu','','{"numbers": ["Band 8.0+", "Target Median", "1400+"], "labels": ["Target Band", "Average Improvement", "Target SAT"]}',ARRAY['{"title": "Proven Score Trajectories", "blocks": [{"t": "p", "v": "Validated scores from Ikorodu candidates across 2023\u20132024 cohorts."}]}','{"title": "The 4 Global Examination Disciplines", "blocks": [{"t": "p", "v": "Every program is structured with modular diagnostics, timed algorithmic testing, and individual examiner reviews designed specifically to shatter admission and licensing thresholds."}, {"t": "h3", "v": "Digital SAT Intensive"}, {"t": "p", "v": "Full adaptation to the College Board''s multi-stage adaptive testing paradigm. We prepare students in Ikorodu to compete directly for prestigious Ivy League and US institutional merit awards."}, {"t": "list", "v": ["Desmos Graphing Calculator Drills: Mastery of rapid mathematical shortcuts embedded directly in Bluebook."]}, {"t": "list", "v": ["Reading & Writing Module Adaptability: Rhetorical synthesis, vocabulary in context, and analytical passages."]}, {"t": "list", "v": ["Diagnostic Scoring: Weekly full-length timed diagnostic exams inside our CBT simulation suite."]}, {"t": "h3", "v": "IELTS Academic & General"}, {"t": "p", "v": "Authoritative training for healthcare professionals (GMC/NMC registration), postgraduate university applicants, and global talent visas requiring verified English proficiency."}, {"t": "list", "v": ["Acoustic Listening Lab: Real exam condition testing with active noise-canceling stereo headsets."]}, {"t": "list", "v": ["Band 8.0+ Task 2 Essay Templates: Logical coherence, lexical resource conditioning, and grammatical precision."]}, {"t": "list", "v": ["1-on-1 Speaking Mocks: Rigorous interview sessions recorded and evaluated on fluency, pronunciation, and lexical range."]}, {"t": "h3", "v": "TOEFL iBT Academic"}, {"t": "p", "v": "Tailored specifically for North American graduate admissions, institutional fellowship grants, and STEM candidates requiring university-level computer-based English evaluation."}, {"t": "list", "v": ["Integrated Speaking Syntheses: Fast note-taking tactics connecting lecture audio with dense academic texts."]}, {"t": "list", "v": ["Speed Reading Strategies: Rapid inference and factual question decomposition under tight countdown timers."]}, {"t": "list", "v": ["Academic Discussion Writing: Formulating spontaneous, structured perspectives for modern ETS writing tasks."]}, {"t": "h3", "v": "GRE General Graduate Track"}, {"t": "p", "v": "Rigorous quantitative traps elimination and verbal vocabulary deconstruction designed to unlock fully funded research assistantships and competitive graduate fellowships."}, {"t": "list", "v": ["Quantitative Trap Deconstruction: Data sufficiency, algebra shortcuts, and statistical pitfalls."]}, {"t": "list", "v": ["Etymological Root Mastery: Deconstruction of 1,200 high-frequency academic verbal roots and nuance markers."]}, {"t": "list", "v": ["Analytical Writing Assessment: 4.5+ score architectural critique frameworks for the Issue essay."]}]}','{"title": "Our Honest Scope & Institutional Charter", "blocks": [{"t": "h3", "v": "verified_user What ADJ Educational Consultants Delivers"}, {"t": "p", "v": "We are an academic coaching institute and standardized testing preparatory clinic. In formal association with Greater Heights Tutorial Center , our work is strictly educational:"}, {"t": "list", "v": ["Syllabus & Exam Mechanics Mastery: Deep tactical instruction on test question architectures, speed, and timing rules."]}, {"t": "list", "v": ["Official Test Registration Logistics: Step-by-step assistance booking verified seats at authorized ETS & British Council test centers across Lagos."]}, {"t": "list", "v": ["Statement of Purpose & Academic Writing: Review of resumes, motivation essays, and scholarship cover letters."]}, {"t": "h3", "v": "gavel What We Do NOT Do (Ethical Boundaries)"}, {"t": "p", "v": "Unlike commercial travel operators and unregulated storefront agents, ADJ upholds total academic transparency:"}, {"t": "list", "v": ["close No Fake Visas or Embassy Promises: We are teachers and academic consultants, not an embassy or visa expediter."]}, {"t": "list", "v": ["close No ''Guaranteed'' Immigration Passports: We do not sell fraudulent work permits, study-abroad packages, or deceptive guarantees."]}, {"t": "list", "v": ["close Group-Only Scope Disclaimer: Our classes operate on transparent group coaching models focused strictly on educational benchmarks."]}]}','{"title": "In-Center Acoustic & Digital Simulation Lab", "blocks": [{"t": "p", "v": "Preparing for international computer-delivered tests on a mobile phone or noisy home computer leads to test-day anxiety and lower performance. Our dedicated center in Banana Estate / Laara offers genuine exam conditions:"}, {"t": "h4", "v": "Acoustic Audio-Isolated Pods"}, {"t": "p", "v": "Equipped with active noise-canceling headsets for genuine IELTS Listening tests and timed TOEFL speaking response drills."}, {"t": "h4", "v": "Bluebook\u2122 Digital SAT Terminals"}, {"t": "p", "v": "Configured with exact screen resolutions, internal Desmos graphing engines, and uninterrupted solar inverter battery backup."}, {"t": "h4", "v": "Algorithmic Error Diagnosis"}, {"t": "p", "v": "Candidates receive full question-by-question analytics to identify timing bottlenecks in reading and quantitative traps."}]}','{"title": "Structured For High-Performing Schedules", "blocks": [{"t": "p", "v": "Designed for secondary school leavers, working civil servants, medical practitioners, and busy professionals living or commuting across the Ikorodu division."}, {"t": "h3", "v": "Weekend Executive Clinic"}, {"t": "p", "v": "Tailored for doctors, nurses, university graduates, and secondary school graduates unable to attend during business hours. Intensive classroom drills + computer lab access."}, {"t": "list", "v": ["In-person physical attendance at Banana Estate / Laara Campus"]}, {"t": "list", "v": ["Full weekend access to CBT diagnostic terminals"]}, {"t": "list", "v": ["Complete British Council / ETS official hardcopy textbook materials"]}, {"t": "h3", "v": "Weekday Evening Accelerated"}, {"t": "p", "v": "Participate from anywhere via live high-definition Zoom streams or attend at the center. Features fully recorded session archives for revision after busy workdays."}, {"t": "list", "v": ["HD Live-streamed whiteboard instruction + questions"]}, {"t": "list", "v": ["Permanent video lecture recordings access through portal"]}, {"t": "list", "v": ["Remote digital simulation diagnostic tests graded within 24 hours"]}]}','{"title": "Request Free International Test Assessment & Diagnostic", "blocks": [{"t": "p", "v": "Establish your current baseline band or SAT percentile before investing in official registrations. An ADJ Senior Academic Specialist will assess your diagnostic test within 24 business hours."}]}']) on conflict(slug) do update set h1=excluded.h1,lead=excluded.lead,stats=excluded.stats,sections=excluded.sections;
insert into program_pages(slug,h1,lead,stats,sections) values('admissions','Admissions Processing & CAPS Guidance: Coaching Until Matriculation','High JAMB scores alone don''t guarantee admission. Our strategic admissions counseling navigates Post-UTME screening, JAMB CAPS marketplace transfers, catchment area quotas, and O-Level subject blending so you never lose your deserved seat.','{"numbers": ["100%", "CAPS Cleared", "5 Stage"], "labels": ["Clearance Rate", "Average Improvement", "Lifecycle Stages"]}',ARRAY['{"title": "Uncompromising Admission Integrity", "blocks": [{"t": "p", "v": "UNILAG, LASU, UI, OAU, FUTA departmental quota qualifiers."}]}','{"title": "The 5 Hidden Pitfalls That Disqualify 270+ JAMB Candidates", "blocks": [{"t": "p", "v": "Every admission cycle in Lagos State, thousands of ambitious scholars score well above 250 in the UTME yet end up without admission. The shortfall is rarely academic capacity\u2014it is procedural and regulatory disqualification."}, {"t": "h3", "v": "Catchment & Federal Quota Misalignment"}, {"t": "p", "v": "Federal universities distribute admissions via: 45% National Merit , 35% Catchment Area , and 20% Educationally Less Developed States (ELDS) . Applying to institutions like UNILORIN or UNIBEN as an applicant from Lagos/Ogun without hitting pure national merit thresholds immediately surrenders your slot to local catchment candidates."}, {"t": "h3", "v": "Subject Combination Nuances"}, {"t": "p", "v": "Faculty requirements differ subtly across institutions. For instance, UNILAG Accounting strictly rejects Commerce in place of Economics, while LASU permits particular commercial substitutions. A candidate scoring 290 with the wrong 4-subject combination faces immediate automated disqualification."}, {"t": "h3", "v": "Ignored JAMB CAPS Marketplace"}, {"t": "p", "v": "When candidates miss the departmental cutoff, universities often transfer them into allied courses via the CAPS marketplace. You have a strict 72 to 120-hour window to review and accept transfer proposals. Ignoring or misinterpreting this portal action results in permanent forfeiture."}, {"t": "h3", "v": "O-Level Blending & Sitting Penalties"}, {"t": "p", "v": "Blending WAEC and NECO is widely permitted, but premier faculties (e.g. UNILAG College of Medicine) strictly mandate ONE sitting with 5 distinctions. Combining sittings without assessing individual school weighting deduction equations leads to sudden rejection at the physical clearance phase."}, {"t": "h3", "v": "Underestimating Aggregate Formulas"}, {"t": "p", "v": "Different institutions execute radically distinct composite weighting metrics: UNILAG uses 50% UTME + 30% Post-UTME CBT + 20% O-Level; LASU executes a pure 50:50 O-level point system alongside UTME score. Misunderstanding this causes candidates to falsely overestimate their competitive footing."}]}','{"title": "Our 5-Stage Matriculation Lifecycle Protocol", "blocks": [{"t": "p", "v": "From initial score appraisal to the moment your clearance dossier is stamped at the academic affairs office, we actively govern every stage of the admissions pipeline."}, {"t": "h3", "v": "Brochure & Realistic Target Institution Matching"}, {"t": "p", "v": "We analyze the candidate''s exact raw score against 5-year historic departmental cut-offs. If a 248 is insufficient for Pharmacy at UNILAG, we execute a rapid, data-backed institutional reassignment to institutions where that score guarantees a merit-list position."}, {"t": "h3", "v": "School-Specific Post-UTME Mock CBT Drills"}, {"t": "p", "v": "We run tailored computer-based screening drills mirroring individual university test patterns: UNILAG\u2019s 30-minute 40-question speed endurance; OAU\u2019s specialized Aptitude Test; and UI\u2019s strict departmental problem sets at our Banana Estate lab."}, {"t": "h3", "v": "Daily JAMB CAPS Central Monitoring"}, {"t": "p", "v": "Admissions officers update candidates at irregular hours. Our academic planning desk conducts daily status tracking: from \"Not Admitted\" to \"Recommended\", \"Approved\", and \"Accepted\", verifying that your O-level upload was never silently dropped by JAMB system syncs."}, {"t": "h3", "v": "Remedial Action & Program Transfer Advisory"}, {"t": "p", "v": "If primary departmental cutoffs shift upward due to anomalous national scores, we trigger immediate program transfer strategies within the same institution or transition the candidate into accredited Direct Entry (JUPEB) pipelines to prevent sitting out a gap year."}, {"t": "h3", "v": "Final Clearance & Matriculation Follow-Through"}, {"t": "p", "v": "Our contract does not end at CAPS acceptance. We assist with screening document dossiers (original JAMB admission letter, attestation letters, local government identification certificates, clinic medical screenings) until matriculation number assignment."}]}','{"title": "Institutional Nuances & Quota Architecture", "blocks": [{"t": "p", "v": "Decisions made specifically for scholars in Ikorodu targeting premier Southwest federal and state universities."}, {"t": "h3", "v": "University of Lagos (UNILAG)"}, {"t": "p", "v": "Lagos, Ogun, Osun, Oyo, Ondo, Ekiti"}, {"t": "h3", "v": "Lagos State University (LASU)"}, {"t": "p", "v": "Lagos State Indigeneship Verification (IIVC) Required"}, {"t": "h3", "v": "UI (Ibadan) & OAU (Ile-Ife)"}, {"t": "p", "v": "Ultra-Competitive Merit & Regional Quotas"}]}','{"title": "Reserve Your Free Diagnostic Admissions Audit", "blocks": [{"t": "p", "v": "Meet directly with our Head of Academic Planning either in-person at our Banana Estate / Laara Centre in Ikorodu or via live Zoom. We will analyze your UTME score, evaluate your O-Level combinations, and present a risk-calculated institutional roadmap."}, {"t": "h4", "v": "Audit Protocol Covers:"}, {"t": "list", "v": ["Aggregate Score Calculation: UNILAG, LASU, UI exact point breakdown."]}, {"t": "list", "v": ["CAPS Readiness Audit: Verification of O-Level upload on the JAMB central server."]}, {"t": "list", "v": ["Change of Course Evaluation: Identifying high-probability supplementary departments."]}, {"t": "list", "v": ["Catchment Quota Review: Validating state-of-origin certificate legitimacy."]}, {"t": "h3", "v": "Candidate Assessment Submission"}, {"t": "p", "v": "Confidential review under our Admissions Processing Advisory Policy."}]}','{"title": "From Ikorodu Secondary Schools to University Matriculation", "blocks": [{"t": "p", "v": "\"I scored 274 in JAMB and thought I had lost UNILAG Computer Science when the first merit cutoff came out at 281. ADJ immediately guided my CAPS marketplace acceptance into Systems Engineering within 48 hours. I matriculated without a gap year.\""}]}']) on conflict(slug) do update set h1=excluded.h1,lead=excluded.lead,stats=excluded.stats,sections=excluded.sections;
insert into program_pages(slug,h1,lead,stats,sections) values('cbt','Timed CBT Practice Lab: Exam-Hall Conditions Before Exam Day','Overcome computer anxiety and pacing problems. Practice inside our dedicated desktop terminal suite calibrated exactly to official testing interfaces.','{"numbers": ["180 Qs", "Made Median", "120 min"], "labels": ["Per Mock Marathon", "Average Improvement", "Timed Conditions"]}',ARRAY['{"title": "Why the Lab Exists", "blocks": [{"t": "p", "v": "Total cognitive conditioning under stressful simulated testing conditions identical to the official JAMB testing protocol."}, {"t": "list", "v": ["Exact 8-key keyboard navigation practice", "Immediate score breakdown & review", "Weak-subject question clustering"]}]}','{"title": "Speed & Accuracy Drills in the Laara Computer Lab", "blocks": [{"t": "p", "v": "Transition from manual pen-and-paper mastery to computerized operational agility inside our dedicated Greater Heights partner lab."}, {"t": "list", "v": ["Elimination of mouse reliance: drill keyboard shortcuts (A, B, C, D, N, P, S).", "Sub-40-second problem-solving metrics for calculation-heavy disciplines.", "Real-time heatmaps identifying syllabus weak points on student dashboard."]}]}','{"title": "Full-Scale Timed Mock Marathons", "blocks": [{"t": "p", "v": "Pressure-test psychological conditioning to eradicate test anxiety and panic stalls."}, {"t": "list", "v": ["Bi-weekly Saturday mock marathons running 180 questions in exactly 120 minutes.", "Post-mock one-on-one strategy review with seasoned ADJ Lead Examiners."]}]}','{"title": "The Facility Behind the Terminals", "blocks": [{"t": "p", "v": "ADJ Educational Consultants conducts its rigorous CBT simulation tracks and physical cohorts in strategic collaboration with Greater Heights Tutorial Center at Banana Estate / Laara, Ikorodu."}, {"t": "list", "v": ["Low-latency offline LAN servers guaranteeing zero test interruptions or disconnects.", "Dual industrial solar inverters and standby generators preventing power dips during timed runs.", "Ergonomic seating environment mirroring the pristine conditions of federal university test halls.", "Strict invigilation enforcing JAMB code of conduct, timing protocols, and exam composure."]}]}','{"title": "Book Your Lab Slot", "blocks": [{"t": "p", "v": "Take a complimentary 90-minute timed mock in our Laara CBT lab. Receive an immediate breakdown of your speed per subject, syllabus deficiency gaps, and a confirmed assessment of your course eligibility."}, {"t": "h3", "v": "Weekly Mock Access"}, {"t": "p", "v": "No consultation fee required. Physical and online slots available."}]}']) on conflict(slug) do update set h1=excluded.h1,lead=excluded.lead,stats=excluded.stats,sections=excluded.sections;
insert into page_sections(page,h1,lead,sections) values('programmes','Academic Pathways & Exam Preparation Tracks','Rigorous, curriculum-aligned preparatory tracks for physical group lectures in Igbe-Laara, Ikorodu, complemented by live high-interaction online cohorts for matriculation excellence across Nigerian and international tertiary boards.',ARRAY['{"title": "Learning Modalities Comparison", "blocks": [{"t": "p", "v": "Choose between structured on-premise immersion in Banana Estate, Ikorodu or live tutor-led remote cohorts built for focused learners."}, {"t": "table", "v": {"head": ["Evaluation Criteria", "Physical Group Classes Banana Estate / Laara Centre (Greater Heights Partner)", "Live Online Interactive Cohorts Google Classroom & Zoom with Dedicated Archive"], "rows": [["Primary Location & Catchment", "Off Igbe Road, Banana Estate / Laara, Ikorodu. Direct access for students from Igbogbo, Elepe, Agunfoye, and Oreta.", "Accessible anywhere with an internet-connected tablet or PC; optimized for low-bandwidth cellular data."], ["Class Size & Scholar Supervision", "Maximum 22 scholars per hall Supervised desk discipline and mobile phone locking during lecture hours.", "Maximum 28 scholars per live stream Weekly attendance tracking and mandatory video participation checks."], ["Practical Science & Experiments", "Full access to wet chemistry apparatus, biological specimens, optical benches, and physics mechanics rigs.", "Digital simulated virtual experiments with high-definition video apparatus guides and real-time calculation reviews."], ["CBT Simulation Experience", "Daily in-lab terminal drills on authentic JAMB 8-key terminals with exam hall noise conditioning.", "Cloud-based browser mock software with identical question bank, automated grading, and timed alerts."], ["Missed Class Archive", "Physical printed lecture notes provided by center tutor; weekend recap clinics available on Saturdays.", "24/7 video recording access stored on Google Classroom portal with downloadable annotated PDFs."], ["Weekly Parent Accountability Reports", "Physical report card issuance and Bi-weekly SMS/WhatsApp test performance report to parents.", "Automated weekly email report with test scores, screen attendance, and assignment completion flags."]]}}]}','{"title": "Academic Calendar & Intake Batches", "blocks": [{"t": "p", "v": "Planned milestone dates ensure scholars cover the exhaustive secondary curriculum with minimum 6 weeks reserved purely for past papers and speed drills."}, {"t": "h3", "v": "Harmattan Comprehensive"}, {"t": "p", "v": "Full foundational lecture coverage starting with primary principles across all four subjects. Built for high aggregate targets (UTME 280+)."}, {"t": "h3", "v": "Rain Accelerated Sprint"}, {"t": "p", "v": "Paced revision track targeting high-yield subject concepts, heavy question solving, formula memorization tricks, and past exam trends."}, {"t": "h3", "v": "Crash Mock Drill Batch"}, {"t": "p", "v": "Pure exam condition rehearsal for the final month before official exams. Zero introductory lectures\u2014pure timed drills and error rectifications."}]}','{"title": "Unsure Which Exam Track Matches Your Goal?", "blocks": [{"t": "p", "v": "Book a free 20-minute diagnostic session with our Head of Academic Planning in Banana Estate / Laara or virtually. We audit past report cards, diagnose weak subject topics, and formulate a realistic path toward university matriculation."}, {"t": "h3", "v": "Request Free Consultation"}, {"t": "p", "v": "Enter candidate details. Our counseling team calls within 4 business hours."}]}']) on conflict(page) do update set h1=excluded.h1,lead=excluded.lead,sections=excluded.sections;
insert into page_sections(page,h1,lead,sections) values('about','Built on Academic Rigor, Grounded in Ikorodu Community Trust.','Eliminating the punishing two-hour trek to Lagos Island and Ikeja. ADJ Educational Consultants was founded to deliver premier university preparatory instruction, authentic CBT simulation, and structured matriculation stewardship directly to families across Igbe-Laara, Igbogbo, Elepe, and Oreta.',ARRAY['{"title": "Four Non-Negotiable Pillars of the ADJ Standard", "blocks": [{"t": "p", "v": "In an educational landscape clouded by transactional promises and quick fixes, our pedagogy rests upon four uncompromising institutional principles designed to produce permanent academic resilience."}, {"t": "h3", "v": "Strict Group-Only Learning"}, {"t": "p", "v": "We strictly reject isolated 1-on-1 home drills. Candidates advance through rigorous, synchronized syllabus milestones in cohesive cohorts, unlocking mutual peer accountability and healthy intellectual friction."}, {"t": "h3", "v": "Coaching Until Matriculation"}, {"t": "p", "v": "Our contractual responsibility does not end when JAMB or WAEC results are released. We counsel students through Post-UTME, JAMB CAPS transfers, subject combination blending, and formal clearance."}, {"t": "h3", "v": "Honest Scope & Zero Gimmicks"}, {"t": "p", "v": "No \"miracle centers\", no illegal leaked materials, and zero false assurances. We teach pure syllabus mastery, time-management techniques, and genuine cognitive preparedness that withstands scrutiny."}, {"t": "h3", "v": "Free First Diagnostic"}, {"t": "p", "v": "A risk-free evaluation milestone. Prospective candidates and parents receive an empirical breakdown of subject deficits before payment or formal enrollment, ensuring total alignment and transparency."}]}','{"title": "The Greater Heights Tutorial Center Facility", "blocks": [{"t": "p", "v": "Academic consultation requires tangible infrastructure. Through our foundational co-location partnership with Greater Heights Tutorial Center at Banana Estate / Laara, ADJ candidates access accredited high-yield physical resources within short transit of Laara Bus Stop and Central Mosque."}, {"t": "h4", "v": "50+ Networked CBT Practice Workstations"}, {"t": "p", "v": "JAMB UTME and Post-UTME timed exam engines mirroring the authentic interface, question bank randomness, and keyboard navigation."}, {"t": "h4", "v": "Uninterrupted Dedicated Power Grid"}, {"t": "p", "v": "Dual industrial generators and solar-inverter backup guarantee uninterrupted mock assessments and evening intensive sessions."}, {"t": "h4", "v": "Equipped Science Wet-Laboratory"}, {"t": "p", "v": "Dedicated titration, specimen analysis, and physics apparatus benches for WAEC/NECO/JUPEB practical mastery."}, {"t": "h4", "v": "Acoustic, Climate-Controlled Lecture Halls"}, {"t": "p", "v": "Tiered, ergonomic group seating shielded from external noise to optimize intense 3-hour subject immersion blocks."}]}','{"title": "Academic Board & Admissions Counselors", "blocks": [{"t": "p", "v": "Our directors and senior tutors bring seasoned familiarity with the stringent intake criteria of premier institutions: UNILAG, LASU, UI, and OAU."}, {"t": "h3", "v": "Dr. A. D. Jinadu, Ph.D."}, {"t": "p", "v": "Academic Planning & Pedagogy Director"}, {"t": "h3", "v": "Mrs. T. F. Oladipo, M.Ed."}, {"t": "p", "v": "Head of Tertiary Admissions & CAPS Advisory"}, {"t": "h3", "v": "Engr. K. M. Balogun"}, {"t": "p", "v": "Chief Science & CBT Testing Coordinator"}, {"t": "h4", "v": "Deep Roots Across the Ikorodu Division"}, {"t": "p", "v": "Dedicated transport route coordination and group study pick-ups for students from Oriwu College, Government College Ikorodu, and premier private colleges in Igbogbo, Elepe, and Baiyeku."}, {"t": "h3", "v": "Walk Into the Laara Center This Week"}, {"t": "p", "v": "Bring your previous WAEC/JAMB printouts or baseline notes. Parents and candidates are welcome for face-to-face evaluations with our academic deans with zero high-pressure sales tactics."}]}','{"title": "Meet an Academic Advisor at Laara Center", "blocks": [{"t": "p", "v": "Reserve a 30-minute one-on-one session for parent and scholar. We inspect past performance, analyze target faculty cut-off benchmarks, and map the optimal preparation track."}]}']) on conflict(page) do update set h1=excluded.h1,lead=excluded.lead,sections=excluded.sections;
insert into page_sections(page,h1,lead,sections) values('contact','Book a Free Consultation & Visit Us in Igbe-Laara','Take the first decisive step toward academic matriculation. Meet experienced educators, evaluate baseline subject proficiency, and establish an unbroken path to 300+ JAMB or clean WAEC distinctions.',ARRAY['{"title": "100% Free First Session", "blocks": [{"t": "p", "v": "Diagnostic assessment, curriculum roadmap, and transparent fee schedule with zero obligation. Parents are warmly welcomed to attend together with candidates."}, {"t": "h3", "v": "Student Consultation Application"}, {"t": "p", "v": "Please provide complete details so our subject matter directors can prepare tailored mock materials for your first meeting."}, {"t": "h4", "v": "Physical Address"}, {"t": "p", "v": "Off Igbe Road, Banana Estate / Laara, Igbe-Laara, Ikorodu, Lagos State."}, {"t": "h4", "v": "Consultation & Office Hours"}, {"t": "p", "v": "Monday \u2013 Saturday: 8:00 AM \u2013 6:00 PM"}, {"t": "h4", "v": "Nearby Neighborhood Transit"}, {"t": "p", "v": "Students regularly commute from surrounding Ikorodu secondary school districts with direct tricycles and shuttle buses:"}]}','{"title": "Frequently Asked Questions & Transit Directions", "blocks": [{"t": "p", "v": "Clear navigation instructions whether you are coming from Ikorodu Central, Benson, or commuting from outlying communities."}, {"t": "h3", "v": "How do I get here from Ikorodu Garage / Benson?"}, {"t": "p", "v": "From Ikorodu Garage, board a bus or tricycle heading toward Igbogbo / Igbe Road . Alight at Laara Bus Stop . From Laara Bus Stop, enter Banana Estate street opposite the Community Central Mosque; ADJ consultants is hosted within the Greater Heights complex 150 meters inwards."}, {"t": "h3", "v": "What should students bring to the Diagnostic Session?"}, {"t": "p", "v": "Please bring previous term results, mock reports, or prior JAMB/WAEC slips if available. Candidates should also bring writing materials for the brief 30-minute subject assessment. Calculators are provided inside our CBT Practice Lab."}, {"t": "h3", "v": "Can distant or working candidates consult online?"}, {"t": "p", "v": "Yes. If you reside outside Ikorodu (or work during daytime hours for IELTS/Direct Entry), select the ''Live Online'' radio option above. We will send a secured Google Meet or Zoom appointment link accompanied by our digital diagnostic portal credentials."}, {"t": "h3", "v": "Consultation Reserved!"}, {"t": "p", "v": "Thank you for trusting ADJ Educational Consultants. Our student admissions desk in Igbe-Laara will confirm your appointment via WhatsApp and SMS shortly."}]}']) on conflict(page) do update set h1=excluded.h1,lead=excluded.lead,sections=excluded.sections;
insert into faqs(grp,q,a,sort) values('home','Where exactly are you located?','Our office sits just off Igbe Road in the Banana Estate / Laara zone of Igbe-Laara, Ikorodu â within walking distance of Laara Bus Stop and the Igbe Laara Community Central Mosque. Our tutorial partner, Greater Heights Tutorial Center, is at Satellite Phase, Igbe-Laara.',0);
insert into faqs(grp,q,a,sort) values('home','Do you offer physical classes, online classes, or both?','Both. We run physical group classes at our Laara centre and live online group tutorials for students who can''t attend in person. Note: we don''t offer private one-on-one coaching â every class is a focused group session.',1);
insert into faqs(grp,q,a,sort) values('home','Which exams do you prepare candidates for?','JAMB/UTME, WAEC, NECO, GCE and JUPEB directly, plus IELTS, TOEFL, SAT and GRE in partnership with Greater Heights Tutorial Center. We also support exam registration and admission processing.',2);
insert into faqs(grp,q,a,sort) values('home','Do you help with admission after the exams?','Yes â admission processing is a core service. Post-UTME screening preparation, course and school selection, O-level blending advice, and follow-through until admission is secured.',3);
insert into faqs(grp,q,a,sort) values('home','How do I start?','Book a free consultation using the form below or chat with us on WhatsApp. We''ll assess where you are, recommend a programme (physical or online), and get you into the next available cohort.',4);
insert into faqs(grp,q,a,sort) values('home','Do you offer study abroad placement?','No â we currently don''t handle study abroad admissions or visas. Our international-exam prep (IELTS, TOEFL, SAT, GRE) gives you the scores you''ll need, and we''ll point you to trusted partners for the placement step.',5);
insert into faqs(grp,q,a,sort) values('programmes','Which exam should my child prepare for first?','It depends on their class. SS3 students typically face WAEC and NECO first, then JAMB/UTME. School leavers may add GCE or JUPEB. Book a free consultation and we''ll map the exact sequence for your child''s situation.',0);
insert into faqs(grp,q,a,sort) values('programmes','Can my child switch programmes mid-term?','Yes. If assessment shows a different exam needs priority â say JAMB over WAEC â we move the student into the right cohort. You never pay twice for the switch; fees follow the student, confirmed during consultation.',1);
insert into faqs(grp,q,a,sort) values('programmes','Do you take complete beginners?','Yes. Every programme starts with an assessment so the tutors know exactly where the student stands, and group placement matches their level. Beginners get foundation weeks before joining the main pace.',2);
insert into faqs(grp,q,a,sort) values('programmes','My child lives outside Ikorodu. Can they still join?','Yes â through the live online group tutorials, which follow the same syllabus, drills and mocks as the physical classes in Laara.',3);
insert into faqs(grp,q,a,sort) values('programmes','Why don''t you publish your fees?','Because the right programme â and therefore the fee â depends on the student''s exams, level and format. Fees are confirmed during the free consultation, before any commitment. No surprises, no pressure.',4);
insert into faqs(grp,q,a,sort) values('results','Are these real results?','The stories on this page are currently samples illustrating the outcomes our programmes target. Real, consented results with names, exams and scores replace them as each admission season concludes.',0);
insert into faqs(grp,q,a,sort) values('results','Do you guarantee admission?','No â and you should distrust any centre that does. What we guarantee is the preparation: syllabus coverage, timed drills, mocks, and follow-through on every admission step within our control.',1);
insert into faqs(grp,q,a,sort) values('results','Can I see full score breakdowns?','Yes. During your consultation we walk through detailed, consented result records from past candidates â every score shown is published with the candidate''s (or parent''s) written permission.',2);
insert into faqs(grp,q,a,sort) values('contact','Can we just walk into the office?','Yes. Walk-ins are welcome during opening hours â off Igbe Road, a short walk from Laara Bus Stop. Booking ahead on WhatsApp means a counsellor is ready for you when you arrive.',0);
insert into faqs(grp,q,a,sort) values('contact','Is the first consultation really free?','Yes. Assessment, programme recommendation and fee confirmation all happen in the free consultation. You commit to nothing until you''ve seen the plan.',1);
insert into faqs(grp,q,a,sort) values('contact','Can we visit before committing?','Absolutely â we encourage it. Come and see a live group class, meet the tutors, and ask past candidates'' parents anything before you decide.',2);
insert into faqs(grp,q,a,sort) values('contact','How fast do you reply on WhatsApp?','Within the same working day, usually much faster during opening hours. [OWNER: confirm reply-time promise]',3);
